INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DOOM: Collector''s Edition', 'Created in conjunction with Triforce, the DOOM Collector''s Edition includes an exclusive, fully-realized 12" tall collector''s statue of one of DOOM''s most iconic demons: the Revenant. Made of high-quality PVC and modeled from actual in-game 3D files, the Revenant stands on an LED-lit base with internal, slow-spinning turbine from the UAC facility on Mars. The DOOM Collector''s Edition also includes the highly-anticipated game, packaged in an exclusive metal case.' FROM games WHERE igdb_id = 41614 ON CONFLICT (game_id, language_code) DO NOTHING;
