INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Bionicle: Mask of Control', 'A Simple 3D Fighting game tie in to the second year of Bionicle''s second generation. you play as three Toa, Tahu, Lewa and Pohatu against Skull Warriors and Umarak the Hunter on a quest for the Mask of Control. The game would later recieve an update in summer of 2016 that adds the last three toa, Gali, Onua and Kopaka, along new levels and the final battle.' FROM games WHERE igdb_id = 343362 ON CONFLICT (game_id, language_code) DO NOTHING;
