INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakahaza', 'BAKAHAZA is a Japanese mobile game for iOS and Android phones. The title is a portmonteau of the collaboration name "Shōnen Bakabon" × "BIOHAZARD". It is a reimagining of the 1996 Resident Evil title with the cast of Tensai Bakabon taking the place of the cast. It was released on Android in 2017.' FROM games WHERE igdb_id = 356215 ON CONFLICT (game_id, language_code) DO NOTHING;
