INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party: Fushigi no Challenge World', 'Mario Party: Fushigi no Challenge World is an arcade game based on Mario Party 9 that was developed by Capcom, and is the sixth Mario Party arcade game from the same developer. The main attraction of the machine is the virtual roulette board in the center. The game supports up to six players.' FROM games WHERE igdb_id = 58941 ON CONFLICT (game_id, language_code) DO NOTHING;
