INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eon Altar: Episode 2 - Whispers in the Catacombs', 'The Siege of Tarnum has been broken: the remaining sellsword forces are scattered and their commander defeated. Having dealt with the Wolf of Yriel, your commitment to the Brotherhood of Keepers has been fulfilled. However, your victory is short lived. Cultists wielding the chaotic forces of their shattered god are waking the dead beneath Tarnum, twisting their forms and warping their minds into madness.' FROM games WHERE igdb_id = 24875 ON CONFLICT (game_id, language_code) DO NOTHING;
