INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubonic: OutBreak', 'You are in debt, your wife and kids have left and you have nothing left to lose, but how far will this take you? It is just another regular day at the office as a private detective and you find on your desk a letter from a friend tipping you off to something good. What will you find? Only time will tell...' FROM games WHERE igdb_id = 36243 ON CONFLICT (game_id, language_code) DO NOTHING;
