INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Jam: Crush It!', 'Monster Jam: Crush It! features a massive variety of game modes with online and offline leaderboards and a colossal emphasis on stadium events, big stunts and destruction. The game offers classic, competitive stadium racing and freestyle, and gives gamers the ability to perform gravity-defying stunts for huge rewards throughout over 96 different challenges in survivor, stunt and hill climb race modes. Out-of-stadium experiences include action in polar, desert, harbor and forest environments, powered by Unreal Engine 4, with main music produced by Somatone Interactive. There are 24 fully licensed and playable trucks to choose from in Monster Jam: Crush It!, including real-life legends like Grave Digger, Monster Mutt, Blue Thunder and ZombieTM. The game captures a cinematic, live-event feel across six genuine Monster Jam arenas.' FROM games WHERE igdb_id = 42932 ON CONFLICT (game_id, language_code) DO NOTHING;
