INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Sweeper', 'Dragon Sweeper is a mix between mine sweeper, classic NES era JRPGs and modern twitch games. Dragon Sweeper is designed to give you the full experience of a classic RPG in a shorter play session. Your job is to rid the land of monsters and kill the dragon that lives on the island. Dragon Sweeper has several randomly generated islands filled with land to explore, towns to visit and monsters to defeat.' FROM games WHERE igdb_id = 182023 ON CONFLICT (game_id, language_code) DO NOTHING;
