INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gears of War 4: Ultimate Edition', 'A new saga begins for one of the most acclaimed video game franchises in history. After narrowly escaping an attack on their village, JD Fenix and his friends, Kait and Del, must rescue the ones they love and discover the source of a monstrous new enemy. Includes the base game, a collectible SteelBook and Season Pass*. Gears of War 4 Ultimate Edition is your gateway to Early Access for Gears of War 4, allowing you play on Friday, October 7 - four days before the game''s standard release date. Season Pass includes the exclusive Vintage VIP Pack, one year of unlimited map access, early access to an exclusive VIP playlist and six Gear Packs.' FROM games WHERE igdb_id = 41627 ON CONFLICT (game_id, language_code) DO NOTHING;
