INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deios II: Deidia', 'Deidia is an exploration glitch-venture game where you explore a lonely unstable world, with glitches, forgotten ruins, and unknown lands abandoned in lonely BBS systems. Corrupt the world to find new paths. Find the worlds behind a thousand doors, lost mysteries, hidden ruins, and loot your discoveries for gain and profit.' FROM games WHERE igdb_id = 26366 ON CONFLICT (game_id, language_code) DO NOTHING;
