INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Transformers Rescue Bots: Hero Adventures', 'Budge Studios presents Transformers Rescue Bots: Hero! Volcanoes, earthquakes, avalanches, or wildfires — wherever there are disasters, wherever there are people in need of help, you can always count on the Rescue Bots. Work together as a team to rescue the civilians of Griffin Rock from hazardous disasters and Doctor Morocco’s evil Morbots. Complete each mission successfully to earn badges. Transformers Rescue Bots, roll to the rescue!' FROM games WHERE igdb_id = 294680 ON CONFLICT (game_id, language_code) DO NOTHING;
