INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: The Fountain of Youth', 'Eipix proudly presents the next installment of the popular Hidden Expedition series! While supervising a restoration project in Sigiriya, your fellow H.E.L.P. agents have gone missing! Follow in the path of Ferdinand Magellan''s historic voyage to locate your coworkers, and uncover what Aturnin''s crew is really looking for. Travel the world in this compelling hidden-object puzzle adventure!' FROM games WHERE igdb_id = 101961 ON CONFLICT (game_id, language_code) DO NOTHING;
