INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winchester', 'Annabelle is on her way home to San Francisco when she crashes her car. Her injuries lead her to the house, and the history of all that has happened within. Mrs. Hannover lives here, and has forced her help onto Annabelle. The house is off-putting and soon reveals its secret history to Annabelle, who becomes increasingly desperate to escape.' FROM games WHERE igdb_id = 233335 ON CONFLICT (game_id, language_code) DO NOTHING;
