INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time to Dodge', 'Time to Dodge is a retro-inspired arcade video game, that has elements of action, minimalist graphics and electro-pop music with infinite and replayable gameplay. In the game the player must dodge different blocks using their reflections, using the intelligence and wisdom to choose well his own way, getting as many coins and score to unlock new characters and game modes.' FROM games WHERE igdb_id = 24068 ON CONFLICT (game_id, language_code) DO NOTHING;
