INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Place in the Sun', 'A Place In The Sun is a short point & click adventure game with an interface similar to the classical games from Lucas Arts. You play the protagonist in his endeavour to make some coffee to survive yet another night of overworking, while trying to handle his complaining ex-wife as well as to cope with his bad conscience regarding his neglected daughter. For players familiar with adventure games it shouldn''t take more than 30-45 minutes to complete the game, while for players unfamiliar with the genre it will probably take a bit longer.' FROM games WHERE igdb_id = 305424 ON CONFLICT (game_id, language_code) DO NOTHING;
