INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrath of the Fire God', 'Wrath of the Fire God is a Vive VR rail shooter. Our goal is to make an immersive VR game that doesn''t require teleporting or movement with a joy stick. You are on a moving platform which takes you slowly through the Fire God''s realm. The Fire God''s guards are trying to stop you from retrieving the 4 magical gems stolen from your village. Unleash your arrows on the enemies and recover the lost gems!' FROM games WHERE igdb_id = 22721 ON CONFLICT (game_id, language_code) DO NOTHING;
