INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cats!', 'Cats! is a cat-based parody of some of the top video games of all time, all from a cat''s perspective! The game also features a "Pet Toy" mode so that your pet can interact with the game. Just leave your pet alone with your screen on and let your pet try to chase and catch various objects on screen.' FROM games WHERE igdb_id = 34772 ON CONFLICT (game_id, language_code) DO NOTHING;
