INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bounce', 'Bounce is a VR physics-based puzzle game for the HTC Vive and Oculus Touch. Under the supervision of H8-Bit and 2Bit, two robots tasked with overseeing security of the intergalactic spaceship, players must help D1G-B, their spherical robot companion, traverse levels using an array of gadgets at their disposal to exit each level’s portal. With moving obstacles, laser gates, gravity wells, and multi-floor levels obstructing the path of D1G-B, players will have to use their creativity to construct solutions.' FROM games WHERE igdb_id = 27679 ON CONFLICT (game_id, language_code) DO NOTHING;
