INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tentacles: Enter the Mind', 'In Tentacles: Enter the Mind you play as the adorable and fantastical creature, Lemmy, and tap or click your way through the layers of Dr. Phluff''s outrageously bizarre mind. Dispatch enemies, collect eyes and secret eggs, gain powers and abilities, and play against your friends. And when you get to the end: survive as long as you can. The Doctor has gone mad from the creatures and only you and Lemmy can save him!' FROM games WHERE igdb_id = 106258 ON CONFLICT (game_id, language_code) DO NOTHING;
