INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gear.Club', 'Gear.Club is much more than a quick adrenaline rush; it is an authentic world of cars. Realistic driving experience, with fully simulated engines, powertrains, suspensions, and aerodynamics. You will get to explore breathtaking settings and compete live with your online friends and foes through unlimited races, championships, and events. Gear.Club offers a full range of options for the cars. Players can collect, upgrade and customize some of the most gorgeous exotic vehicles in their performance shop and enjoy details including engine and interiors in full HD.' FROM games WHERE igdb_id = 55983 ON CONFLICT (game_id, language_code) DO NOTHING;
