INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Bullets', 'Mad Bullets, the wackiest shooter is here to put your reflexes and laughing muscles to an intensive test. You can forget about boring stories, complicated controls and irritating tutorials, and jump right into a mind blowing, high-speed action. Now is the time to become the hero of the Wild West and shoot your way up to the top of the leaderboards! Do you think you have what it takes to face a real challenge?' FROM games WHERE igdb_id = 33262 ON CONFLICT (game_id, language_code) DO NOTHING;
