INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Samurai', 'Dead Samurai is an intense and action-packed online fighting game that puts you in the shoes of a skilled samurai warrior. Set in a feudal Japanese backdrop, your mission is to engage in deadly combat against various adversaries, including other skilled warriors and fearsome creatures. Grab your blade and get ready to walk the path of the Dead Samurai in this intense hack ''n'' slash game. Your objective is to win all duels to become the best swordsman.' FROM games WHERE igdb_id = 377465 ON CONFLICT (game_id, language_code) DO NOTHING;
