INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krautscape', 'Krautscape is an action-packed racing game with bird-like flying cars, focused on competitive multiplayer gameplay. The leading player actively builds the racetrack while the chasing players can take shortcuts by flying off the track to overcome obstacles. But the track is needed to score and to get speed – the vehicles don''t have any thrusters to accelerate while flying. The three multiplayer game modes are designed to support nonlinear gameplay and intelligent movement instead of forcing you to drive perfectly.' FROM games WHERE igdb_id = 16903 ON CONFLICT (game_id, language_code) DO NOTHING;
