INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EmergeNYC', 'EmergeNYC is a genre-bending simulation of New York City''s Emergency Services. Drive over 30 different firetrucks, police cars, and ambulances alone, or with up to 32 of your friends through busy New York City Streets with blazing sirens and air horns. The game will be set in a fictional dynamic open-world recreation of Manhattan and will give the players the opportunity to step foot in the shoes of a firefighter, police officer, or emergency medical services worker in the Big Apple. They will also be able to act as a dispatcher or incident commander with the ability to manage an emergency scene or operation from above in a real time strategy fashion.' FROM games WHERE igdb_id = 33045 ON CONFLICT (game_id, language_code) DO NOTHING;
