INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cloudphobia', 'In this pulse-pounding arcade style shoot ''em up, players control giant armored robots, loaded with hi-tech weaponry. Chose from two types of mechs: the PLG-90, armed with a high-tech laser rifle or the NúllPunktur with the Vibroblade! Comprised of five 3-minute episodes, players must protect the mothership while slashing, shooting and boosting their way to the end of each level and defeat the boss within the time limit.' FROM games WHERE igdb_id = 36194 ON CONFLICT (game_id, language_code) DO NOTHING;
