INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deputy Dangle', 'You are Deputy Dangle and today you''re getting deputized. Everything is going great until the elusive criminal, known only as GMA, decides to crash the party. Within minutes of becoming a deputy you''re now hot on the trail of Dangleton''s most infamous criminal. Use your powers of climbing, flopping, grappling, and flailing along with your partner Chongo to catch GMA and save the day.' FROM games WHERE igdb_id = 35615 ON CONFLICT (game_id, language_code) DO NOTHING;
