INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rexodus: A VR Story Experience', 'Rexodus: A VR Story Experience is based on the Dark Horse Graphic Novel Rexodus. This is a VR narrative experience set in a universe where dinosaurs didn''t go extinct, they left Earth. Those dinosaurs, utilizing their own advanced technology, are traversing the galaxy. Encounter new locations, characters, and dangerous enemies in Rexodus: A VR Story Experience!' FROM games WHERE igdb_id = 32665 ON CONFLICT (game_id, language_code) DO NOTHING;
