INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turnabout Steampunk', 'It is an Ace Attorney RPG in a steampunk world of magic power and steam machines, by SophiaSW and RabbitonBooks.Trucy Wright, lived with her baker farther in Phoenix Town, the most remote little town in the Fey Kingdom. One day, Detective Ema visited the Wright Bakery during her investigation to a neighboring country...and Trucy decided to travel along as her assistant. A lost treasure, murder cases, airships, cities faraway...in this vast and exciting world, what lies in the end of their journey?' FROM games WHERE igdb_id = 318775 ON CONFLICT (game_id, language_code) DO NOTHING;
