INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trending Pharaoh', 'Trending Pharaoh is a satirical idle/clicker game set in Ancient Egypt, where pharaohs and queens compete for social media dominance. Players manage the vanity‑driven lives of rulers like Ramses, Cleopatra, Xerxes, and Nefertiti, posting on parody platforms such as Meowerrr, SphynxBook, Insta‑Ra, and Tinubis. The goal: gain followers, boost influence, and outshine rival monarchs in a tongue‑in‑cheek take on modern online culture' FROM games WHERE igdb_id = 109515 ON CONFLICT (game_id, language_code) DO NOTHING;
