INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jubeat Prop', 'Jubeat (pronounced you-beat) is a rhythm game based on the properly timed presses of squares on a 4x4 grid. The game became a breakout hit in Japan due to online multiplayer, tons of unlockable extras, and a songlist filled with variety and popular licenses.' FROM games WHERE igdb_id = 268568 ON CONFLICT (game_id, language_code) DO NOTHING;
