INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('submerged-miku-and-the-sunken-city', 91219, '2016-09-06', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submerged: Miku and the Sunken City', 'Submerged is a third-person combat-free game in which you explore a mysterious flooded city and discover the beauty of desolation in vast outdoor environments. You take on the role of Miku, a young girl who has brought her wounded brother to the city in their small fishing boat. Navigate the flooded city streets by boat, scale the drowned buildings, and use your telescope to scour the city for the supplies needed to save your dying sibling. As you explore the city at your own pace, you encounter the habitat that flourishes in this colorful place and discover hidden objects that piece together the story of a broken world and a broken family.' FROM games WHERE igdb_id = 91219 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 91219 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
