INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shmups-skill-test', 33834, '2016-06-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4122.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark3w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shmups Skill Test', 'Some say you’re only as old as you feel. Shmups Skill Test says you’re only as old as you shoot! Shmups Skill Test is a clever way to evaluate your shmup skills in the form of a "gamer age". Challenge and unlock shoot-’em-up-based minigames in a gauntlet of shmup nostalgia goodness.' FROM games WHERE igdb_id = 33834 ON CONFLICT (game_id, language_code) DO NOTHING;
