INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from Sin City', 'Escape from Sin City is a challenging escape-room style adventure set in the grim and desolate town of Basin City. You play as a lone survivor — a man of faith — navigating a college ravaged by a zombie apocalypse. The game emphasizes logic-based puzzles, code-cracking, and item usage across multiple eerie locations. With a dark narrative tone and horror elements, players must escape before time runs out.' FROM games WHERE igdb_id = 101498 ON CONFLICT (game_id, language_code) DO NOTHING;
