INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mother Russia Bleeds: Dealer Edition', 'Mother Russia Bleeds is an ultra-violent co-op brawler overflowing with an unmistakable style and unforgettably brutal action for up to four players at once. Set in an alternate U.S.S.R, the story centers on a desperate crew of imprisoned street fighters that must overcome an oppressive criminal authority and forced drug addictions through any means necessary. Battle solo or alongside friends in an exceptional story mode campaign or harden your resolve in the savage Survival Mode.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 51834 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
