INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vintage VR', 'In the 19th century, when people had no HTC Vives to play with, they resorted to using primitive stereoscopes to see stereoscopic images in 3D! This free VR experience allows you to view a collection of over 700 such images from that era and enjoy them as people saw them over a century ago.' FROM games WHERE igdb_id = 32749 ON CONFLICT (game_id, language_code) DO NOTHING;
