INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice in Wonderland: Puzzle Golf Adventures', 'Don’t be late and get ready for the most eclectic and eccentric Puzzle Golf Adventure, Alice’s Wonderland has even seen! You are the ball! Go down the rabbit hole in over 70+ clever and sometimes diabolical puzzle levels. Aim, roll and explore the fantastical world of Alice’s Puzzle Golf Adventures, inspired by the famous Lewis Carroll novels. The Mad Hatter awaits! Or will chasing the White Rabbit drive you mad in the process?!' FROM games WHERE igdb_id = 100008 ON CONFLICT (game_id, language_code) DO NOTHING;
