INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Calling: Anabel', 'On her deathbed, the Queen announced that when she passed, all magic would die with her. But she also foretold that one day, her last living heir would return, restoring the land to its former glory. Years ago, your father set off to explore the Midnight Castle and hasn’t been heard from since. Now, a strange vision of him haunts your dreams, calling out to you for rescue!' FROM games WHERE igdb_id = 91139 ON CONFLICT (game_id, language_code) DO NOTHING;
