INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murasaki Mist: Akara''s Journey', 'Hack N'' Slash Action RPG set in a fantasy world unlike any other. Accompany Akara in a long journey that will take her to the deep bowels of Hell itself. A Nuclear holocaust, real-life alchemist Fulcanelli, a wandering historian and Hell based on the paintings by Mexican muralists all revolve around this exclusive adventure. Gameplay is fast-paced, many monsters and demons attack you frenetically while the player hacks its way through.' FROM games WHERE igdb_id = 61043 ON CONFLICT (game_id, language_code) DO NOTHING;
