INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cargo Cult: Shoot''n''Loot VR', 'Have you ever dreamt of being a brave captain of air battleship? Enter with us the world of total cargo cult! Battle against fast swarms of Iron Hornets, mad Kamikadze Ships, heavy and armored Doomcopters, merciless Missile Towers, and more. Cargo Cult: Shoot''n''Loot VR will give you all of these and even more! Shoot crowds of armed to the teeth opponents and collect variety of treasures in an exciting VR experience.' FROM games WHERE igdb_id = 30258 ON CONFLICT (game_id, language_code) DO NOTHING;
