INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 46021 AND rs.code = 'ESRB' AND r.code = 'E' ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ruin', 17021, '2016-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2r7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mztkorylnfgiqtxvl9sq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RUiN', 'RUiN is a game deeply rooted in the PvP - player versus player - tradition. While similar games have opted for an expansion in both strategical and mechanical usage, RUiN opts to head the other direction. We create fun and depth from simplicity. Our game stands tall on the fact that it''s built on pure, intense combat. Players select their preferred set of skills from an ever-expanding pool and duke it out on various dynamic arenas. RUiN is set in a fantasy world that mirrors the core values of the game; it''s vibrant, fantastic and of course intensely fun.' FROM games WHERE igdb_id = 17021 ON CONFLICT (game_id, language_code) DO NOTHING;
