INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bric', 'Bric is an intense randomized level game with pleasing smoothness in gameplay. You''re a ball trying to move forward avoiding death from various black objects and avoid getting crushed by the white bars that close in on you while you move forward through levels. Try to beat your last high score by jumping and maneuvering around the obstacles ahead, discovering new ways to get around these levels.' FROM games WHERE igdb_id = 31124 ON CONFLICT (game_id, language_code) DO NOTHING;
